import os, json, time

class DiskCache:
    """A tiny JSON-on-disk cache with per-entry TTL."""

    def __init__(self, root: str, ttl: float, now=time.time):
        self.root = root
        self.ttl = ttl
        self._now = now
        os.makedirs(root, exist_ok=True)
        # Clean up any expired entries already on disk
        try:
            for name in os.listdir(root):
                if not name.endswith('.json'):
                    continue
                p = os.path.join(root, name)
                try:
                    with open(p) as f:
                        rec = json.load(f)
                except Exception:
                    # ignore malformed files
                    continue
                t = rec.get('t')
                if t is None:
                    continue
                if self._now() - t > self.ttl:
                    try:
                        os.remove(p)
                    except Exception:
                        pass
        except Exception:
            # ignore any filesystem errors during cleanup
            pass

    def _path(self, key):
        return os.path.join(self.root, f"{key}.json")

    def set(self, key, value):
        with open(self._path(key), "w") as f:
            json.dump({"t": self._now(), "v": value}, f)

    def get(self, key, default=None):
        p = self._path(key)
        if not os.path.exists(p):
            return default
        try:
            with open(p) as f:
                rec = json.load(f)
        except Exception:
            # if file is unreadable, treat as missing
            try:
                os.remove(p)
            except Exception:
                pass
            return default
        t = rec.get('t')
        if t is None:
            # malformed record, remove and treat as missing
            try:
                os.remove(p)
            except Exception:
                pass
            return default
        if self._now() - t > self.ttl:
            try:
                os.remove(p)
            except Exception:
                pass
            return default
        return rec.get("v")
